cd /workspace && python3 - << 'EOF'
import json, subprocess, sys
cases = json.load(open('/workspace/examples/fixtures.json'))
case = cases[1]
raw = json.dumps(case['input']).encode()
import os
os.makedirs('/workspace/tmp', exist_ok=True)
p = subprocess.run([sys.executable, '-I', '-B', '/workspace/submission/campaign.py'],
                   input=raw, capture_output=True, cwd='/workspace/tmp')
out = json.loads(p.stdout)
exp = case['expected']
def diff(a, b, path=''):
    if type(a) != type(b): print(path, 'TYPE', type(a), type(b)); return
    if isinstance(a, dict):
        for k in set(a) | set(b):
            if k not in a: print(path+'/'+k, 'missing in output')
            elif k not in b: print(path+'/'+k, 'EXTRA in output:', json.dumps(a[k])[:200])
            else: diff(a[k], b[k], path+'/'+k)
    elif isinstance(a, list):
        if len(a) != len(b): print(path, 'LEN', len(a), len(b))
        for i, (x, y) in enumerate(zip(a, b)): diff(x, y, path+f'[{i}]')
    elif a != b: print(path, 'VALUE', json.dumps(a)[:120], '!=', json.dumps(b)[:120])
diff(out, exp)
print('--- stdout:', p.stdout.decode()[:400])
print('--- stderr:', p.stderr.decode()[:400])
EOF
